"use client";

import React, { useState, forwardRef } from "react";
import { AnimatePresence, motion, usePresenceData, wrap } from "motion/react";
import { ArrowLeft, ArrowRight, Sparkles } from "lucide-react";
import { cn } from "@/lib/utils";

const PALETTE = [
  { id: 1, name: "Sunset Rose", color: "bg-pink-500", border: "border-pink-500", text: "text-pink-500" },
  { id: 2, name: "Neon Violet", color: "bg-purple-600", border: "border-purple-500", text: "text-purple-500" },
  { id: 3, name: "Electric Indigo", color: "bg-indigo-500", border: "border-indigo-500", text: "text-indigo-500" },
  { id: 4, name: "Cyan Horizon", color: "bg-cyan-500", border: "border-cyan-500", text: "text-cyan-500" },
  { id: 5, name: "Emerald Glade", color: "bg-emerald-500", border: "border-emerald-500", text: "text-emerald-500" },
  { id: 6, name: "Amber Glow", color: "bg-amber-500", border: "border-amber-500", text: "text-amber-500" },
];

const Slide = forwardRef<
  HTMLDivElement,
  { item: typeof PALETTE[0] }
>(function Slide({ item }, ref) {
  const direction = (usePresenceData() as number) ?? 1;

  return (
    <motion.div
      ref={ref}
      initial={{ opacity: 0, x: direction * 80, scale: 0.8 }}
      animate={{
        opacity: 1,
        x: 0,
        scale: 1,
        transition: {
          delay: 0.05,
          type: "spring",
          stiffness: 400,
          damping: 26,
        },
      }}
      exit={{
        opacity: 0,
        x: direction * -80,
        scale: 0.8,
        transition: {
          duration: 0.2,
          ease: "easeInOut",
        },
      }}
      className={cn(
        "flex flex-col items-center justify-center h-48 w-48 rounded-3xl text-white shadow-2xl p-6 text-center select-none",
        item.color
      )}
    >
      <span className="text-3xl font-black">{item.id}</span>
      <span className="text-xs font-bold uppercase tracking-wider mt-2 opacity-90">
        {item.name}
      </span>
    </motion.div>
  );
});

export function UsePresenceData({ className }: { className?: string }) {
  const [selectedIndex, setSelectedIndex] = useState(0);
  const [direction, setDirection] = useState<1 | -1>(1);

  function setSlide(newDirection: 1 | -1) {
    const nextIndex = wrap(0, PALETTE.length, selectedIndex + newDirection);
    setSelectedIndex(nextIndex);
    setDirection(newDirection);
  }

  const currentItem = PALETTE[selectedIndex];

  return (
    <div
      data-slot="use-presence-data"
      className={cn(
        "flex flex-col items-center justify-center gap-6 p-8 w-full max-w-md mx-auto select-none rounded-3xl border border-neutral-200 bg-white dark:border-neutral-800 dark:bg-neutral-950 shadow-2xl",
        className
      )}
    >
      <div className="flex items-center justify-between w-full px-2">
        <div className="flex items-center gap-2">
          <Sparkles className={cn("h-4 w-4", currentItem.text)} />
          <span className="text-xs font-bold uppercase tracking-wider text-neutral-800 dark:text-neutral-200 font-mono">
            usePresenceData
          </span>
        </div>
        <span className="text-xs font-mono text-neutral-500">
          Slide {selectedIndex + 1} / {PALETTE.length}
        </span>
      </div>

      {/* Interactive Carousel Frame */}
      <div className="relative flex items-center justify-center gap-4 w-full h-56">
        <motion.button
          type="button"
          aria-label="Previous Slide"
          whileTap={{ scale: 0.9 }}
          whileHover={{ scale: 1.1 }}
          onClick={() => setSlide(-1)}
          className="z-10 flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 shadow-md transition-colors hover:bg-neutral-200 dark:hover:bg-neutral-700 cursor-pointer"
        >
          <ArrowLeft className="h-4 w-4" />
        </motion.button>

        <div className="relative flex h-48 w-48 items-center justify-center">
          <AnimatePresence
            custom={direction}
            initial={false}
            mode="popLayout"
          >
            <Slide key={currentItem.id} item={currentItem} />
          </AnimatePresence>
        </div>

        <motion.button
          type="button"
          aria-label="Next Slide"
          whileTap={{ scale: 0.9 }}
          whileHover={{ scale: 1.1 }}
          onClick={() => setSlide(1)}
          className="z-10 flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 shadow-md transition-colors hover:bg-neutral-200 dark:hover:bg-neutral-700 cursor-pointer"
        >
          <ArrowRight className="h-4 w-4" />
        </motion.button>
      </div>

      <p className="text-xs text-muted-foreground font-mono text-center">
        Exiting slides read transition direction via usePresenceData()
      </p>
    </div>
  );
}
